<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('checkoutForm'),district=document.getElementById('district'),upazila=document.getElementById('upazila'),submit=document.getElementById('placeOrder'),csrf=form.querySelector('[name="<?= csrf_token() ?>"]');district.addEventListener('change',async()=>{submit.disabled=true;upazila.disabled=true;upazila.innerHTML='<option>লোড হচ্ছে...</option>';const rows=await fetch('<?= site_url('api/locations/upazilas') ?>/'+district.value).then(r=>r.json());upazila.innerHTML='<option value="">উপজেলা নির্বাচন করুন</option>'+rows.map(x=>`<option value="${x.id}">${x.name_bn||x.name_en}</option>`).join('');upazila.disabled=false});upazila.addEventListener('change',async()=>{submit.disabled=true;const body=new URLSearchParams({district_id:district.value,upazila_id:upazila.value});body.append('<?= csrf_token() ?>',csrf.value);const response=await fetch('<?= url_to('checkout.delivery') ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const data=await response.json();if(data.csrf_hash)csrf.value=data.csrf_hash;if(data.ok){document.getElementById('deliveryAmount').textContent='৳'+data.delivery_charge;document.getElementById('grandTotal').textContent='৳'+data.grand_total;document.getElementById('deliveryMessage').textContent=data.estimate||'';submit.disabled=false}else document.getElementById('deliveryMessage').textContent=data.message});document.querySelectorAll('[data-payment-type]').forEach(radio=>radio.addEventListener('change',()=>{const manual=radio.dataset.paymentType==='manual_mobile_banking';document.getElementById('manualPayment').classList.toggle('d-none',!manual);document.getElementById('transactionId').required=manual}))});</script>
<?php if($customer): ?><script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('checkoutForm'),card=form.querySelectorAll('.checkout-card')[1];if(card){const wrap=document.createElement('div');wrap.className='form-check mt-3';wrap.innerHTML='<input class="form-check-input" type="checkbox" name="save_address" value="1" id="saveAddress"><label class="form-check-label" for="saveAddress">Save this address for next time</label>';card.append(wrap)}const saved=<?= json_encode($address ? ['name'=>$address['recipient_name'],'mobile'=>$address['mobile'],'area'=>$address['area'],'landmark'=>$address['landmark'],'address_line'=>$address['address_line']] : [], JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;for(const [name,value] of Object.entries(saved)){const field=form.elements.namedItem(name);if(field&&!field.value)field.value=value||''}const district=document.getElementById('district'),selectedDistrict=<?= (int)old('district_id',$selectedDistrictId??0) ?>,selectedUpazila=<?= (int)old('upazila_id',$selectedUpazilaId??0) ?>;if(selectedDistrict&&!district.value){district.value=selectedDistrict;district.dispatchEvent(new Event('change'));const timer=setInterval(()=>{const upazila=document.getElementById('upazila');if(!upazila.disabled&&upazila.options.length>1){clearInterval(timer);if(selectedUpazila){upazila.value=selectedUpazila;upazila.dispatchEvent(new Event('change'))}}},100);setTimeout(()=>clearInterval(timer),5000)}});</script><?php endif ?>
<?php if(!$customer && old('district_id')): ?><script>document.addEventListener('DOMContentLoaded',()=>{const district=document.getElementById('district');district.value=<?= (int)old('district_id') ?>;district.dispatchEvent(new Event('change'));const timer=setInterval(()=>{const upazila=document.getElementById('upazila');if(!upazila.disabled&&upazila.options.length>1){clearInterval(timer);upazila.value=<?= (int)old('upazila_id') ?>;if(upazila.value)upazila.dispatchEvent(new Event('change'))}},100);setTimeout(()=>clearInterval(timer),5000)});</script><?php endif ?>
<script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-payment-type]').forEach(radio=>radio.addEventListener('change',()=>{const manual=['manual_mobile_banking','manual_bank_transfer'].includes(radio.dataset.paymentType);document.getElementById('manualPayment').classList.toggle('d-none',!manual);document.getElementById('transactionId').required=manual;const label=document.querySelector('#manualPayment label');if(label)label.textContent=radio.dataset.paymentType==='manual_bank_transfer'?'Deposit / transfer reference *':'Transaction ID *';document.querySelector('#manualPayment [name="sender_mobile"]')?.closest('.col-md-6')?.classList.toggle('d-none',radio.dataset.paymentType==='manual_bank_transfer')}));});</script>
<?php $courierCondition=array_values(array_filter($methods,static fn($method)=>$method['code']==='courier_condition'))[0]??null; ?>
<?php if($courierCondition): ?><script>document.addEventListener('DOMContentLoaded',()=>{const courierId='<?= (int)$courierCondition['id'] ?>',subtotal=<?= json_encode((float)$cart['subtotal']) ?>,radios=[...document.querySelectorAll('[name="payment_method_id"]')],courier=radios.find(r=>r.value===courierId),manual=document.getElementById('manualPayment'),transaction=document.getElementById('transactionId'),sender=manual?.querySelector('[name="sender_mobile"]'),deliveryAmount=document.getElementById('deliveryAmount'),grandTotal=document.getElementById('grandTotal'),deliveryRow=deliveryAmount?.parentElement,totalRow=grandTotal?.parentElement,subtotalRow=deliveryRow?.previousElementSibling;let delivery=0;if(!courier)return;const notice=document.createElement('div');notice.className='courier-condition-notice';notice.innerHTML='<strong>ডেলিভারি চার্জ অগ্রিম পরিশোধ আবশ্যক</strong><span>কুরিয়ার Condition-এ অর্ডার করতে ডেলিভারি চার্জ অগ্রিম পরিশোধ করা বাধ্যতামূলক। পণ্যের মূল্য কুরিয়ার অফিস থেকে পণ্য গ্রহণের সময় পরিশোধ করবেন।</span>';courier.closest('.payment-option')?.append(notice);const update=()=>{const active=courier.checked;if(active){manual?.classList.remove('d-none');if(transaction){transaction.required=true;const label=transaction.closest('.col-md-6')?.querySelector('label');if(label)label.textContent='ডেলিভারি চার্জ পেমেন্ট TrxID *'}if(sender)sender.closest('.col-md-6')?.classList.remove('d-none');if(subtotalRow?.querySelector('span'))subtotalRow.querySelector('span').textContent='পণ্যের মোট মূল্য';if(deliveryRow?.querySelector('span'))deliveryRow.querySelector('span').textContent='ডেলিভারি চার্জ (এখন পরিশোধ করুন)';if(totalRow?.querySelector('span'))totalRow.querySelector('span').textContent='কুরিয়ার অফিসে বকেয়া';if(grandTotal)grandTotal.textContent='৳'+subtotal}else{if(subtotalRow?.querySelector('span'))subtotalRow.querySelector('span').textContent='সাবটোটাল';if(deliveryRow?.querySelector('span'))deliveryRow.querySelector('span').textContent='ডেলিভারি';if(totalRow?.querySelector('span'))totalRow.querySelector('span').textContent='মোট';if(grandTotal)grandTotal.textContent='৳'+(subtotal+delivery)}};new MutationObserver(()=>{const parsed=Number((deliveryAmount.textContent||'').replace(/[^0-9.]/g,''));if(Number.isFinite(parsed))delivery=parsed;update()}).observe(deliveryAmount,{childList:true,characterData:true,subtree:true});radios.forEach(r=>r.addEventListener('change',()=>setTimeout(update,0)));update();});</script><?php endif ?>
<?php $codMethod=array_values(array_filter($methods,static fn($method)=>$method['code']==='cod'))[0]??null; ?>
<?php if($codMethod): ?><script>document.addEventListener('DOMContentLoaded',()=>{const cod=document.querySelector('[name="payment_method_id"][value="<?= (int)$codMethod['id'] ?>"]'),allowed=<?= json_encode(array_values(array_map('intval',$codMethod['allowed_upazila_ids']??[]))) ?>,upazila=document.getElementById('upazila');if(!cod||!upazila)return;const option=cod.closest('.payment-option');const update=()=>{const available=allowed.includes(Number(upazila.value));option.hidden=!available;cod.disabled=!available;if(!available&&cod.checked){const replacement=[...document.querySelectorAll('[name="payment_method_id"]')].find(r=>!r.disabled);if(replacement){replacement.checked=true;replacement.dispatchEvent(new Event('change',{bubbles:true}))}}};upazila.addEventListener('change',update);update()});</script><?php endif ?>
